INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q15844349', 'Battle at Brůdek', 'The Battle at Brůdek (Czech bitva u Brůdku; German Schlacht bei Stokau, Schlacht bei Biwanka) was fought between Henry III, King of the Romans, and Břetislav I, Duke of Bohemia, on 22/23 August 1040. The battle took place in the Upper Palatine Forest in what is now the Domažlice District of Plzeň Region, Czech Republic.', 1040, 8, 23, 1040, 8, 23, 'day', '23 August 1040', 34, 'https://en.wikipedia.org/wiki/Battle_at_Br%C5%AFdek'),
  ('Q233350', 'Second Battle of Chlumec', 'The War of Bohemian Succession (1125–1126) was a war between the Imperial Forces of the Holy Roman Empire and the Duchy of Bohemia about the succession in the Duchy of Bohemia.', 1126, 2, 18, NULL, NULL, NULL, 'day', '18 February 1126', 43, 'https://en.wikipedia.org/wiki/War_of_Bohemian_Succession_(1125%E2%80%931126)'),
  ('Q1468732', 'Battle of Vyšehrad', 'The Battle of Vyšehrad was a series of engagements at the start of the Hussite War between Hussite forces and Catholic crusaders sent by King Sigismund. The battle took place at the castle of Vyšehrad from 16 August 1419 to c.', 1419, 8, 16, 1420, 11, 1, 'day', '16 August 1419 – 1 November 1420', 41, 'https://en.wikipedia.org/wiki/Battle_of_Vy%C5%A1ehrad'),
  ('Q11156922', 'Battle of Živohošť', 'The Battle of Živohošť took place on 4 November 1419 during the Hussite Wars. Hussite pilgrims from Alttabor (Czech: Sezimovo Ústí) came to the countrywide congress in Prague, where they fought the Czech Catholic nobility following King Sigismund of Luxembourg and under the command of Peter Konopišťský of Sternberg.', 1419, 11, 4, NULL, NULL, NULL, 'day', '4 November 1419', 34, 'https://en.wikipedia.org/wiki/Battle_of_%C5%BDivoho%C5%A1t%C4%9B'),
  ('Q1618294', 'Battle of Sudoměř', 'The Battle of Sudoměř was fought on 25 March 1420, between Catholic and Hussite forces. The Hussites were led by Břeněk of Švihov, who was killed in battle, and Jan Žižka, whose forces proved victorious.', 1420, 3, 25, NULL, NULL, NULL, 'day', '25 March 1420', 47, 'https://en.wikipedia.org/wiki/Battle_of_Sudom%C4%9B%C5%99'),
  ('Q3493159', 'Battle of Kutná Hora', 'The Battle of Kutná Hora (Kuttenberg) was an early battle and subsequent campaign in the Hussite Wars, fought on 21 December 1421 between German and Hungarian troops of the Holy Roman Empire and the Hussites, an early ecclesiastical reformist group that was founded in what is now the Czech Republic. In 1419, Pope Martin V declared a crusade against the Hussites.', 1421, 12, 21, NULL, NULL, NULL, 'day', '21 December 1421', 43, 'https://en.wikipedia.org/wiki/Battle_of_Kutn%C3%A1_Hora'),
  ('Q38977', 'Battle of Deutschbrod', 'The Battle of Německý Brod (also Battle of Deutschbrod) took place on 10 January 1422, at Německý Brod in Bohemia, during the Hussite Wars. Led by Jan Žižka, the Hussites besieged the army of Royalist crusaders.', 1422, 1, 10, NULL, NULL, NULL, 'day', '10 January 1422', 34, 'https://en.wikipedia.org/wiki/Battle_of_N%C4%9Bmeck%C3%BD_Brod'),
  ('Q1500196', 'Battle of Hořice', 'The Battle of Hořice (German name: Horschitz) was fought on 27 April 1423, between the Orebites faction of the Hussites and Bohemian Catholics. The Hussites were led by Jan Žižka (who was completely blind at the time of the battle), while the Catholics were led by the repeatedly-converting Čeněk of Wartenberg.', 1423, 4, 27, NULL, NULL, NULL, 'day', '27 April 1423', 43, 'https://en.wikipedia.org/wiki/Battle_of_Ho%C5%99ice'),
  ('Q2237014', 'Battle of Malešov', 'The Battle of Malešov (Czech: Bitva u Malešova) was a battle of the Hussite Wars between the Orebites united armies under the command of Jan Žižka and the Prague Hussites with their Catholic allies that took place on 7 June 1424 near Malešov fortress, about 6 kilometres from Kutná Hora. The clash was won by Žižka''s troops.', 1424, 6, 7, NULL, NULL, NULL, 'day', '7 June 1424', 39, 'https://en.wikipedia.org/wiki/Battle_of_Male%C5%A1ov'),
  ('Q1787589', 'Battle of Aussig', 'The Battle of Aussig (German: Schlacht bei Aussig) was fought on 16 June 1426, between Roman Catholic crusaders and the Hussites during the Fourth Crusade of the Hussite Wars. It was fought near Aussig (Ústí nad Labem) in northern Bohemia.', 1426, 6, 16, NULL, NULL, NULL, 'day', '16 June 1426', 47, 'https://en.wikipedia.org/wiki/Battle_of_Aussig'),
  ('Q1462345', 'Battle of Tachov', 'The Battle of Tachov (German: Schlacht bei Tachau) or Battle of Mies (German: Schlacht bei Mies) was fought on 4 August 1427 near the Bohemian towns of Tachov (Tachau) and Stříbro (Mies). It was part of the Hussite Wars, and it was the first battle in which war wagons were used by the crusaders.', 1427, 8, 3, 1427, 8, 4, 'day', '3 August 1427 – 4 August 1427', 43, 'https://en.wikipedia.org/wiki/Battle_of_Tachov'),
  ('Q1968819', 'Battle of Domažlice', 'The Battle of Domažlice (Czech: Bitva u Domažlic) or Battle of Taus (German: Schlacht bei Taus) or Battle of Tausch was fought on 14 August 1431 as the part of the 5th crusade against Hussites. The crusade was sent to Bohemia after negotiations, held in Pressburg and Cheb, between Hussites and the emperor Sigismund had failed.', 1431, 8, 14, NULL, NULL, NULL, 'day', '14 August 1431', 47, 'https://en.wikipedia.org/wiki/Battle_of_Doma%C5%BElice'),
  ('Q935088', 'Battle of Lipany', 'The Battle of Lipany (Czech: Bitva u Lipan), also called the Battle of Český Brod, was fought at Lipany 40 km east of Prague on 30 May 1434 and virtually ended the Hussite Wars. An army of moderate Hussite (or Calixtine) nobility and Catholics, called the Bohemian League, defeated the radical Taborites and Orphans (or Sirotci) led by Prokop the Great, the overall commander, and by Jan Čapek of Sány, the cavalry commander.', 1434, 5, 30, NULL, NULL, NULL, 'day', '30 May 1434', 56, 'https://en.wikipedia.org/wiki/Battle_of_Lipany'),
  ('Q944855', 'Siege of Pilsen', 'The Siege of Pilsen, 19 September to 21 November 1618, was the first significant action of the Thirty Years'' War. Following the Bohemian Revolt, a Bohemian army under Ernst von Mansfeld captured Plzeň.', 1618, 9, 19, 1618, 11, 21, 'day', '19 September 1618 – 21 November 1618', 56, 'https://en.wikipedia.org/wiki/Siege_of_Pilsen'),
  ('Q2088781', 'Battle of Lomnice', 'The Battle of Lomnice or Lomnice nad Lužnicí occurred on 9 November 1618, during the Bohemian period of the Thirty Years'' War. It was fought between the Habsburg Roman Catholic army of Charles Bonaventure de Longueval, Count of Bucquoy, and the Protestant army of Jindřich Matyáš Thurn.', 1618, 11, 9, NULL, NULL, NULL, 'day', '9 November 1618', 39, 'https://en.wikipedia.org/wiki/Battle_of_Lomnice'),
  ('Q4373', 'Battle of White Mountain', 'The Battle of White Mountain was fought on 8 November 1620 outside Prague in the early stages of the Thirty Years'' War. An army backing Frederick V led by Christian of Anhalt was defeated by forces supporting his rival Ferdinand II, Holy Roman Emperor, under Bucquoy and Count Tilly.', 1620, 11, 8, NULL, NULL, NULL, 'day', '8 November 1620', 75, 'https://en.wikipedia.org/wiki/Battle_of_White_Mountain'),
  ('Q3485845', 'Siege of Brno (1645)', 'The siege of Brno, which occurred from 3 May to 23 August 1645, was the second Swedish siege of the city of Brno in the last years of the Thirty Years'' War. The Brno garrison, consisting of 500 soldiers and about 1,000 Brno residents, successfully defended the city against about 28,000 soldiers of General Lennart Torstensson.', 1645, 5, 3, 1645, 8, 23, 'day', '3 May 1645 – 23 August 1645', 37, 'https://en.wikipedia.org/wiki/Siege_of_Brno'),
  ('Q2237118', 'Battle of Triebl', 'The Battle of Triebl or Battle of Třebel took place on 22 August 1647 during the Thirty Years'' War. Imperial cavalry under Raimondo Montecuccoli and Johann von Werth launched a surprise attack on the Swedish camp of Carl Gustaf Wrangel and inflicted 380, or more than 1,300, losses on them in exchange for 200–300 casualties.', 1647, 8, 18, 1647, 9, 5, 'day', '18 August 1647 – 5 September 1647', 39, 'https://en.wikipedia.org/wiki/Battle_of_Triebl'),
  ('Q3494380', 'Battle of Prague', 'The Battle of Prague, which occurred between 25 July and 1 November 1648 was the last action of the Thirty Years'' War. While the negotiations for the Peace of Westphalia were proceeding, Sweden took the opportunity to mount one last campaign into Bohemia.', 1648, NULL, NULL, 1648, 11, 1, 'year', '1648', 52, 'https://en.wikipedia.org/wiki/Battle_of_Prague_(1648)'),
  ('Q3486003', 'Siege of Prague', 'The 1742 siege of Prague was an extended blockade of the Bohemian capital during the War of the Austrian Succession.', 1742, NULL, NULL, 1742, 12, NULL, 'year', '1742', 43, 'https://en.wikipedia.org/wiki/Siege_of_Prague_(1742)'),
  ('Q694478', 'Battle of Lobositz', 'The Battle of Lobositz or Lovosice also Lowositz on 1 October 1756 was the opening land battle of the Third Silesian War and the wider Seven Years'' War. Frederick the Great''s 28,000 Prussians were prevented by 33,000 Austrians under Maximilian Ulysses Count von Browne from continuing their invasion into the rich Bohemian plain, forcing Frederick to ultimately fall back north into Saxony for the winter.', 1756, 10, 1, NULL, NULL, NULL, 'day', '1 October 1756', 58, 'https://en.wikipedia.org/wiki/Battle_of_Lobositz'),
  ('Q127299', 'Battle of Kolín', 'The Battle of Kolín (Kolin) on 18 June 1757 saw 54,000 Austrians under Count von Daun defeat 34,000 Prussians under Frederick the Great during the Third Silesian War (Seven Years'' War). Prussian attempts to turn the Austrian right flank turned into piecemeal frontal attacks and were defeated in five and a half hours of combat.', 1757, 6, 18, NULL, NULL, NULL, 'day', '18 June 1757', 64, 'https://en.wikipedia.org/wiki/Battle_of_Kol%C3%ADn'),
  ('Q223622', 'Battle of Prague', 'The Battle of Prague, also known as Battle of Štěrboholy, was fought on 6 May 1757, during the Third Silesian War and the broader Seven Years'' War, between the Kingdom of Prussia and Habsburg Austria. Although Frederick the Great''s army of 64,000 Prussians forced 60,000 Austrians to retreat, he lost 14,300 men and decided he was not strong enough to attack Prague.', 1757, 5, 6, NULL, NULL, NULL, 'day', '6 May 1757', 62, 'https://en.wikipedia.org/wiki/Battle_of_%C5%A0t%C4%9Brboholy'),
  ('Q694061', 'Battle of Reichenberg', 'The Battle of Reichenberg took place during the Third Silesian War (part of the Seven Years'' War) on 21 April 1757 near the town of Reichenberg (Czech: Liberec) in Bohemia.', 1757, 4, 21, NULL, NULL, NULL, 'day', '21 April 1757', 56, 'https://en.wikipedia.org/wiki/Battle_of_Reichenberg'),
  ('Q7510328', 'Siege of Prague', 'The Siege of Prague was an unsuccessful attempt by a Prussian army led by Frederick the Great to capture the Bohemian city of Prague during the Third Silesian War (Seven Years'' War). It took place in May 1757 immediately after the Battle of Prague.', 1757, 5, NULL, 1757, 6, NULL, 'month', 'May 1757 – June 1757', 47, 'https://en.wikipedia.org/wiki/Siege_of_Prague'),
  ('Q508088', 'Siege of Olomouc', 'The Siege of Olomouc took place in 1758 when a Prussian army led by Frederick the Great besieged the Austrian city of Olmütz (now Olomouc, Czech Republic) during the Prussian invasion of Moravia in the Third Silesian War (Seven Years'' War). The attempt stalled as the besiegers faced stronger resistance than Frederick had expected.', 1758, NULL, NULL, 1758, 7, 2, 'year', '1758', 48, 'https://en.wikipedia.org/wiki/Siege_of_Olomouc'),
  ('Q134114', 'Battle of Austerlitz', 'The Battle of Austerlitz was fought on Monday 2 December 1805, near Austerlitz (then in the Austrian Empire, now in the Czech Republic), being the decisive engagement of the War of the Third Coalition. The Grande Armée under the command of Emperor Napoleon I defeated a combined Russo-Austrian army.', 1805, 12, 2, NULL, NULL, NULL, 'day', '2 December 1805', 82, 'https://en.wikipedia.org/wiki/Battle_of_Austerlitz'),
  ('Q2890386', 'Battle at Wischau', 'The Battle of Wischau occurred on 28 November 1805 between the Russian and French armies. The conflict resulted in a minor Russian success.', 1805, 11, 28, NULL, NULL, NULL, 'day', '28 November 1805', 34, 'https://en.wikipedia.org/wiki/Battle_of_Wischau'),
  ('Q702099', 'Battle of Znaim', 'Following defeat at the Battle of Wagram, Archduke Charles retreated north into Bohemia hoping to regroup his battered forces. The French army had also suffered in the battle and did not give immediate pursuit.', 1809, 7, 10, 1809, 7, 11, 'day', '10 July 1809 – 11 July 1809', 48, 'https://en.wikipedia.org/wiki/Battle_of_Znaim'),
  ('Q48253', 'Battle of Kulm', 'The Battle of Kulm was fought near the town Kulm (Czech: Chlumec) and the village Přestanov (then called Priesten) in northern Bohemia. It was fought on 29–30 August 1813, during the War of the Sixth Coalition.', 1813, 8, 29, 1813, 8, 30, 'day', '29 August 1813 – 30 August 1813', 61, 'https://en.wikipedia.org/wiki/Battle_of_Kulm'),
  ('Q686474', 'Whitsuntide events in Prague', 'The Prague uprising (Czech: Pražské červnové povstání), also known as the Pentecostal Storm, was an armed conflict on 12–17 June 1848 in Prague, which culminated in the revolutionary process in the Czech lands. The spontaneous uprising was suppressed by the army and killed about 43 people.', 1848, 6, 12, 1848, 6, 17, 'day', '12 June 1848 – 17 June 1848', 45, 'https://en.wikipedia.org/wiki/Prague_uprising_(1848)'),
  ('Q154942', 'Battle of Königgrätz', 'The Battle of Königgrätz (or Battle of Sadová; Czech: Bitva u Hradce Králové) was the decisive battle of the Austro-Prussian War in which the Kingdom of Prussia defeated the Austrian Empire. It took place on 3 July 1866, near the Bohemian city of Hradec Králové (German: Königgrätz) and village of Sadová, now in the Czech Republic.', 1866, 7, 3, NULL, NULL, NULL, 'day', '3 July 1866', 70, 'https://en.wikipedia.org/wiki/Battle_of_K%C3%B6niggr%C3%A4tz'),
  ('Q168268', 'Peace of Prague', 'The Peace of Prague (German: Prager Frieden) was a peace treaty signed by the Kingdom of Prussia and the Austrian Empire at Prague on 23 August 1866. In combination with the treaties of Prussia and several south and central German states, it effectively ended the Austro-Prussian War.', 1866, 8, 23, NULL, NULL, NULL, 'day', '23 August 1866', 68, 'https://en.wikipedia.org/wiki/Peace_of_Prague_(1866)'),
  ('Q466391', 'Battle of Hühnerwasser', 'The Battle of Hühnerwasser (Kuřívody) was the first battle of the Austro-Prussian War. It was the first engagement in the opening days of the Königgrätz campaign, fought in Bohemia on 26 June 1866.', 1866, 6, 26, NULL, NULL, NULL, 'day', '26 June 1866', 45, 'https://en.wikipedia.org/wiki/Battle_of_H%C3%BChnerwasser'),
  ('Q574365', 'Battle of Jičín', 'The Battle of Gitschin or Jičín (German: Schlacht bei Gitschin) took place during the Austro-Prussian War on 29 June 1866, ending with a Prussian victory over the Austrian forces. There is a memorial there today at Jičín in the Czech Republic.', 1866, 6, 29, NULL, NULL, NULL, 'day', '29 June 1866', 48, 'https://en.wikipedia.org/wiki/Battle_of_Gitschin'),
  ('Q656686', 'Battle of Münchengrätz', 'The Battle of Münchengrätz (German: Schlacht bei Münchengrätz) or Battle of Mnichovo Hradiště (Czech: Bitva u Mnichova Hradiště) was fought near Mnichovo Hradiště, modern day Czech Republic, on 28 June 1866 during the Austro-Prussian War. It ended in a Prussian victory over the Austrian Empire.', 1866, 6, 28, NULL, NULL, NULL, 'day', '28 June 1866', 45, 'https://en.wikipedia.org/wiki/Battle_of_M%C3%BCnchengr%C3%A4tz'),
  ('Q670005', 'Battle of Skalitz', 'The Battle of Skalitz was a minor engagement in the Königgratz/Sadowa campaign of the Austro-Prussian War of 1866 in Bohemia on 28 June. Following the Prussian victory at the Battle of Náchod the previous day (27 June), the Prussian forces, led by General of the Infantry Steinmetz, advanced on Skalitz (Česká Skalice) and defeated the forces of Archduke Leopold.', 1866, 6, 28, NULL, NULL, NULL, 'day', '28 June 1866', 48, 'https://en.wikipedia.org/wiki/Battle_of_Skalitz'),
  ('Q689374', 'Battle of Trautenau', 'The Battle of Trautenau (German: Schlacht bei Trautenau) or Battle of Trutnov was fought on 27 June 1866, during the Austro-Prussian War. It was the only major battle of the war that ended in an Austrian victory over the Prussians, but at a large cost.', 1866, 6, 27, NULL, NULL, NULL, 'day', '27 June 1866', 50, 'https://en.wikipedia.org/wiki/Battle_of_Trautenau'),
  ('Q695680', 'Battle of Nachod', 'The Battle of Náchod (German: Nachod) on 27 June 1866 was the first major action of the Austro-Prussian War. The advance guard of General Karl Friedrich von Steinmetz''s 5th Corps occupied some high ground near Náchod as part of a Prussian advance into Bohemia from Silesia.', 1866, 6, 27, NULL, NULL, NULL, 'day', '27 June 1866', 48, 'https://en.wikipedia.org/wiki/Battle_of_N%C3%A1chod'),
  ('Q1497914', 'Battle of Königinhof', 'The Battle of Königinhof was a battle of the Austro-Prussian War, taking place in the town of Königinhof. As one of the preliminary engagements leading up to the Battle of Königgrätz, it resulted in a victory for Prussian forces despite stiff Austrian resistance.', 1866, NULL, NULL, NULL, NULL, NULL, 'year', '1866', 39, 'https://en.wikipedia.org/wiki/Battle_of_K%C3%B6niginhof'),
  ('Q1497929', 'Battle of Schweinschädel', 'The Battle of Schweinschädel (Czech: Bitva u Svinišťan) took place during the Austro-Prussian War between Prussia and Austria on 29 June 1866. The IV Army Corps of the Austrian Army under Tassilo Festetics tried to stop the advance of the Prussian 2nd Army under Crown Prince Friedrich, but was defeated by the V Army Corps under General von Steinmetz and had to withdraw.', 1866, 6, 29, NULL, NULL, NULL, 'day', '29 June 1866', 41, 'https://en.wikipedia.org/wiki/Battle_of_Schweinsch%C3%A4del'),
  ('Q2984891', 'Battle of Burkersdorf', 'The Battle of Burkersdorf was fought on 28 June 1866, during the Austro-Prussian War. It featured the Austrian X Corps against the Prussian Guard Corps and ended in a Prussian victory.', 1866, 6, 28, NULL, NULL, NULL, 'day', '28 June 1866', 39, 'https://en.wikipedia.org/wiki/Battle_of_Burkersdorf_(1866)'),
  ('Q11153999', 'Clash at Habersbirk', 'The Clash at Habersbirk (Czech: Habartov) was the first armed confrontation between the Czechoslovak gendarmerie and the Sudeten Germans. It is sometimes marked as the first battle of the Second World War.', 1938, 9, 13, NULL, NULL, NULL, 'day', '13 September 1938', 39, 'https://en.wikipedia.org/wiki/Clash_at_Habersbirk'),
  ('Q15726836', 'Sudeten German uprising', 'Sudeten German uprising (Czech: sudetoněmecké povstání) in September 1938 was a rebellion of Sudeten Germans against Czechoslovak authorities in Sudetenland, supported by an organized action orchestrated by Sudeten German Party (SdP) chaired by Konrad Henlein. Therefore, the uprising is also referred to as the Henlein''s coup (or coup attempt; Czech: henleinovský puč).', 1938, 10, NULL, NULL, NULL, NULL, 'month', 'October 1938', 47, 'https://en.wikipedia.org/wiki/Sudeten_German_uprising'),
  ('Q666778', 'Prague Uprising', 'The Prague uprising (Czech: Pražské povstání) was a partially successful attempt by the Czech resistance movement to liberate the city of Prague from German occupation in May 1945, during the end of World War II. The preceding six years of occupation had fuelled anti-German sentiment and the rapid advance of Allied forces from the Red Army and the United States Army offered the resistance a chance of success. On 5 May 1945, during the end of World War II in Europe, occupying German forces in Bohemia and Moravia were spontaneously attacked by civilians in an uprising, with Czech resistance…', 1945, 5, 5, NULL, NULL, NULL, 'day', '5 May 1945', 67, 'https://en.wikipedia.org/wiki/Prague_uprising'),
  ('Q697017', 'Ústí massacre', 'The Ústí massacre (Czech: Ústecký masakr, German: Massaker von Aussig) was a lynching of ethnic Germans, triggered by the explosion of an ammunition depot, in Ústí nad Labem (Aussig an der Elbe), a largely ethnic German city in northern parts of the Bohemian Sudetenland, that occurred shortly after the end of World War II, on 31 July 1945. Neither the reason for the explosion nor subsequent pogrom has ever been conclusively identified; the official government investigation following the massacre placed blame on the Werwolf forces (Nazi saboteurs), however the outcome of the investigation…', 1945, 7, 31, NULL, NULL, NULL, 'day', '31 July 1945', 45, 'https://en.wikipedia.org/wiki/%C3%9Ast%C3%AD_massacre'),
  ('Q4870163', 'Battle for Czech Radio', 'An illicit broadcast from the radio studio in Prague helped spark the Prague uprising during the final days of World War II, but German counterattacks led to a pitched battle breaking out. The conflict became known as the Battle for Czech Radio (Czech: Boj o Český rozhlas).', 1945, 5, 5, 1945, 5, 9, 'day', '5 May 1945 – 9 May 1945', 34, 'https://en.wikipedia.org/wiki/Battle_for_Czech_Radio'),
  ('Q110517047', 'Operation Cowboy', 'Operation Cowboy was fought in the town of Hostau, Sudetenland (now Hostouň in the Czech Republic), on 28 April 1945, in the last days of fighting in the European theater of World War II. It is one of two known incidents during the war in which Americans and Germans of the Wehrmacht fought side by side against the Waffen-SS, the other being the Battle of Castle Itter.', 1945, 4, 28, NULL, NULL, NULL, 'day', '28 April 1945', 47, 'https://en.wikipedia.org/wiki/Operation_Cowboy'),
  ('Q540704', 'Treaty of Prague', 'The Treaty of Prague was a treaty signed on 11 December 1973, in Prague, by West Germany and Czechoslovakia in which both states recognised each other diplomatically, declared the 1938 Munich Agreement to be null and void, acknowledged the inviolability of their common borders and abandoned all territorial claims. The Treaty of Prague was a strong element of the Ostpolitik put forward by the German Chancellor Willy Brandt and supported by his ruling party in the Bundestag of the Federal Republic of Germany.', 1973, 12, 11, NULL, NULL, NULL, 'day', '11 December 1973', 45, 'https://en.wikipedia.org/wiki/Treaty_of_Prague_(1973)'),
  ('Q315494', '1997 Central European flood', 'The 1997 Central European flood or the 1997 Oder Flood of the Oder and Morava river basins in July 1997 affected Poland, the Czech Republic and Germany, taking the lives of 114 people and causing material damages estimated at $4.5 billion (3.8 billion euros in the Czech Republic and Poland and 330 million euros in Germany). The flooding began in the Czech Republic, then spread to Poland and Germany.', 1997, 7, 5, 1997, 8, 6, 'day', '5 July 1997 – 6 August 1997', 57, 'https://en.wikipedia.org/wiki/1997_Central_European_flood'),
  ('Q871885', '2009 European floods', 'The 2009 European floods were a series of natural disasters that took place in June 2009 in Central Europe. Austria, the Czech Republic, Germany, Hungary, Poland, Romania, Serbia, Slovakia and Turkey were all affected.', 2009, NULL, NULL, NULL, NULL, NULL, 'year', '2009', 37, 'https://en.wikipedia.org/wiki/2009_European_floods'),
  ('Q282940', '2010 Central European floods', 'The 2010 Central European floods were a devastating series of weather events which occurred across several Central European countries during May and June 2010. Poland was the worst affected.', 2010, 5, 14, 2010, 6, 9, 'day', '14 May 2010 – 9 June 2010', 50, 'https://en.wikipedia.org/wiki/2010_Central_European_floods'),
  ('Q13415210', '2013 European floods', 'Extreme flooding in Central Europe began after several days of heavy rain in late May and early June 2013. Flooding and damages primarily affected south and east German states (Thuringia, Saxony, Saxony-Anhalt, Lower Saxony, Bavaria and Baden-Württemberg), western regions of the Czech Republic (Bohemia), and Austria.', 2013, 5, 28, 2013, 6, 5, 'day', '28 May 2013 – 5 June 2013', 53, 'https://en.wikipedia.org/wiki/2013_European_floods'),
  ('Q18602194', '2014 Vrbětice ammunition warehouse explosions', 'In 2014, two explosions of ammunition depots occurred in Vrbětice, Vlachovice, in the Zlín District of the Czech Republic. The first explosion occurred on 16 October, and the second on 3 December.', 2014, 10, 16, NULL, NULL, NULL, 'day', '16 October 2014', 48, 'https://en.wikipedia.org/wiki/2014_Vrb%C4%9Btice_ammunition_warehouse_explosions'),
  ('Q64800347', 'Je to na nás!', 'Je to na nás! (English: It is up to us!) was a political demonstration held on 23 June 2019, on Letná in Prague, part of a wider series of protests in the country.', 2019, 6, 23, NULL, NULL, NULL, 'day', '23 June 2019', 41, 'https://en.wikipedia.org/wiki/Je_to_na_n%C3%A1s!'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q107529288', '2021 European floods', 'In July 2021, several European countries were affected by severe floods. Some were catastrophic, causing deaths and widespread damage.', 2021, NULL, NULL, 2021, 7, 25, 'year', '2021', 73, 'https://en.wikipedia.org/wiki/2021_European_floods'),
  ('Q130297776', '2024 Central European floods', 'The 2024 Central European floods were a series of floods caused by a record heavy rainfall generated by Storm Boris, an extremely humid Genoa low. The flooding began in Austria and the Czech Republic, then spread to Poland, Romania and Slovakia, and then onwards to Germany and Hungary.', 2024, 9, NULL, NULL, NULL, NULL, 'month', 'September 2024', 57, 'https://en.wikipedia.org/wiki/2024_Central_European_floods'),
  ('Q137366682', '2025 Bulgarian protests', 'Protests began in Bulgaria on 26 November 2025 after the Zhelyazkov government announced a 2026 budget plan that would have increased taxes—specifically, the amounts individuals were to contribute to pension and social-security programs. The government suspended, then withdrew the budget, but demonstrations continued, with protestors demanding the resignation of the government and new elections.', 2025, 11, 26, NULL, NULL, NULL, 'day', '26 November 2025', 48, 'https://en.wikipedia.org/wiki/2025%E2%80%932026_Bulgarian_protests');
